{"term":"revenge porn","lang":"nl","script":"latin","romanization":null,"category":"internet_subculture","subcategory":"non-consensual image sharing","concept":"non_consensual_image_sharing","is_novel_concept":false,"register":"loanword","crude":55,"technical":15,"recognition_pct_current":82,"recognition_pct_peak":86,"peak_year":2016,"regional":null,"definition":"The non-consensual sharing of intimate photographs or videos of a person, typically by a former romantic partner as retaliation; criminalized in the Netherlands since 2018.","english_term":"revenge porn","english_translation_quality":"direct","notes":"The standard Dutch legal and journalistic equivalent is 'wraakporno'; both terms circulate freely in Dutch media."}
